SELECT COLUMN_NAME FROM ALL_TAB_COLUMNS WHERE OWNER='SCM_MGR' AND TABLE_NAME='XIF_ERP_SALES_RESULT_R_SN' AND (COLUMN_NAME LIKE '%AMT%' OR COLUMN_NAME LIKE '%AMOUNT%' OR COLUMN_NAME LIKE '%CURR%' OR COLUMN_NAME LIKE '%COMPANY%' OR COLUMN_NAME LIKE '%DATE%' OR COLUMN_NAME LIKE '%RATE%') ORDER BY COLUMN_ID
